<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api';import{useAuthStore}from'../store/auth';import{ElMessage}from'element-plus';const auth=useAuthStore(),username=ref(auth.user?.username||''),records=ref<any[]>([]),saving=ref(false);onMounted(async()=>records.value=(await api.creditRecords()).items);async function save(){saving.value=true;try{auth.user=await api.updateMe(username.value);ElMessage.success('资料已保存')}finally{saving.value=false}}async function avatar(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;const r=await api.uploadAvatar(f);if(auth.user)auth.user.avatarUrl=r.avatarUrl;ElMessage.success('头像已更新')}</script>
<template><div class="page profile-page"><header class="page-title"><span class="eyebrow">CREATOR PROFILE</span><h1>个人中心</h1><p>管理创作者身份与积分记录。</p></header><div class="profile-grid"><section class="profile-card"><div class="profile-identity"><label class="avatar large"><img v-if="auth.user?.avatarUrl" :src="auth.user.avatarUrl"/><span v-else>{{auth.user?.username.slice(0,1)}}</span><input type="file" accept="image/png,image/jpeg,image/webp" @change="avatar"/><i>更换</i></label><div><h2>{{auth.user?.username}}</h2><p>{{auth.user?.email}}</p><small>创作者 ID · {{auth.user?.id}}</small></div></div><div class="profile-form"><label>创作者名称</label><el-input v-model="username" maxlength="40"/><label>邮箱</label><el-input :model-value="auth.user?.email" disabled/><el-button type="primary" :loading="saving" @click="save">保存资料</el-button></div></section><aside><div class="balance-card"><span>可用积分</span><strong>{{auth.user?.creditBalance}}</strong><p>普通生成 10 积分，Max Mode 20 积分</p></div><div class="records"><div class="section-head"><h3>积分记录</h3><small>最近变动</small></div><article v-for="r in records" :key="r.id"><div><strong>{{r.remark}}</strong><small>{{new Date(r.createdAt).toLocaleString()}}</small></div><b :class="{plus:r.amount>0}">{{r.amount>0?'+':''}}{{r.amount}}</b></article></div></aside></div></div></template>
